    {
      "keystrokes": "cat > trinity-compress.config.json << 'EOF'
{
  "version": "1.0",
  "modes": {
    "balanced": {
      "aggression": 0.5,
      "preserve_code": true,
      "preserve_urls": true,
      "preserve_paths": true,
      "preserve_vars": true,
      "max_line_length": 120
    },
    "aggressive": {
      "aggression": 0.8,
      "preserve_code": true,
      "preserve_urls": true,
      "preserve_paths": true,
      "preserve_vars": true,
      "max_line_length": 80
    },
    "light": {
      "aggression": 0.2,
      "preserve_code": true,
      "preserve_urls": true,
      "preserve_paths": true,
      "preserve_vars": true,
      "max_line_length": 150
    }
  },
  "targets": {
    "prompt_files": ["*.md", "*.txt", "docs/*.md", "docs/*.txt"],
    "exclude": ["node_modules", ".git", "*.bak", "__pycache__"]
